import{u as n,o as r,c as o,j as e,k as s,F as l,a8 as d,e as c,p as h}from"./chunks/framework.fPNBP_58.js";const p=["markdown-url"],g={"data-allow-mismatch":"",style:{display:"none"}},v=JSON.parse('{"title":"High-resolution Forecasts of Solar Potential","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"high-res_forecasts_solar_potential","file":"https://gtif-austria.github.io/public-narratives/high-res_forecasts_solar_potential.md","title":"High-resolution Forecasts of Solar Potential"},"relativePath":"narratives/high-res_forecasts_solar_potential.md","filePath":"narratives/[narrative].md"}'),u={name:"narratives/high-res_forecasts_solar_potential.md"},_=Object.assign(u,{setup(b){const t=h(!0);t.value=!1;const{params:i}=n();return(m,a)=>(r(),o("div",null,[e("client-only",null,[e("eox-storytelling",{"show-nav":"","markdown-url":s(i).file,"show-hero-scroll-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,p)]),e("div",g,[t.value?(r(),o(l,{key:0},[a[0]||(a[0]=d(' --- cover-image: https://raw.githubusercontent.com/triebnigg/public-narratives/triebnigg/evapotranspiration-monitoring-2/assets/triebnigg/solar-potential-1749907032353.webp domain: Energy Transition tags: photovolatic, remote sensing, solar radiation provider: GeoSphere --- <h1 id="high-resolution-forecasts-of-solar-potential" tabindex="-1">High-resolution Forecasts of Solar Potential <a class="header-anchor" href="#high-resolution-forecasts-of-solar-potential" aria-label="Permalink to &quot;High-resolution Forecasts of Solar Potential &lt;!--{ as=&quot;img&quot; mode=&quot;hero&quot; src=&quot;https://raw.githubusercontent.com/triebnigg/public-narratives/triebnigg/evapotranspiration-monitoring-2/assets/triebnigg/solar-potential-1749907032353.webp&quot;}--&gt;&quot;">​</a></h1><p>Every location tells a different story when it comes to solar energy. The amount of sunlight reaching a surface is shaped not only by weather, but also by terrain, surrounding features and local environmental conditions. By combining high-resolution geospatial and meteorological data with physical modelling, this service brings these elements together to uncover the solar radiation and photovoltaic potential of any given area. The result is a detailed spatial and temporal perspective on where solar energy potential lies and how it changes over time.</p><h2 id="about-the-service" tabindex="-1">About the service <a class="header-anchor" href="#about-the-service" aria-label="Permalink to &quot;About the service&quot;">​</a></h2><p>This service combines meteorological data, high-resolution geospatial information and physical modelling approaches. On this basis, near-surface solar radiation and theoretical photovoltaic generation potential are calculated and represented in a spatially and temporally differentiated way.</p><h5 id="what-influences-the-solar-energy-potential" tabindex="-1">What influences the solar energy potential? <a class="header-anchor" href="#what-influences-the-solar-energy-potential" aria-label="Permalink to &quot;What influences the solar energy potential?&quot;">​</a></h5><div id="user-content-toc"> 🌅 <strong>Sun and Weather</strong><ul> ☀️ solar radiation<br> ☁️ cloud cover<br> 🌡️ temperature<br> 🌬️️️ wind<br> 💨 ️dust cover<br> ❄️ snow cover </ul></div><div id="user-content-toc"> 🌅 <strong>Geographic Conditons</strong><ul> 🏔️ topography<br> 🧭 terrain orientation<br> 🌥️ shading<br> 🏢 buildings<br> 🌳 vegetation </ul></div><h5 id="what-does-the-service-deliver" tabindex="-1">What does the service deliver? <a class="header-anchor" href="#what-does-the-service-deliver" aria-label="Permalink to &quot;What does the service deliver?&quot;">​</a></h5><p>The processing chain brings together solar radiation calculations, spatial refinement and photovoltaic modelling. Additional modules can be used to incorporate estimates of dust- and snow-related effects.</p><div style="flex:1;background:#FFFACD;padding:16px;border-radius:10px;"><h5> ☀️ ️Radiation Information</h5><p> Radiation modelling is done with the STRAHLGRID model <br> --&gt; caluclation of direct, diffuse and global radiation <br> --&gt; <strong>100x100m</strong> spatial resolution</p><p> Downscaling to <strong>1x1m</strong> can be performed to include <strong>shading</strong> effects of <strong>buildings</strong> and <strong>vegetation</strong>.</p></div><br><div style="flex:1;background:#C1E1C1;padding:16px;border-radius:10px;"><h5> 🔋 PV potential Information</h5><p>The PV potential modelling combines solar radiation output with <strong>temperature</strong> and <strong>wind</strong> forecasts.</p><p>--&gt; theoretical photovoltaic <strong>potential</strong></p></div><br><div style="flex:1;background:#F1EBFA;padding:16px;border-radius:10px;"><h5> ℹ️ Additional Information</h5><p> The assessment takes account of further relevant <strong>influences</strong> alongside meteorological and geographical conditions. This includes information on <strong>snow cover</strong> and <strong>dust deposition</strong> coverage on photovoltaic modules.</p></div><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Solar radiation:</strong> Calculation of direct, diffuse and global radiation on horizontal surfaces and surfaces following the actual terrain.</li><li><strong>Spatial refinement:</strong> Downscaling of radiation information from 100 × 100 m to a resolution of up to 1 × 1 m, taking local shading by buildings, structures and trees into account.</li><li><strong>Photovoltaic potential:</strong> Estimation of theoretical PV potential based on global radiation, temperature and wind.</li><li><strong>Dust effects:</strong> Model-based estimation of potential soiling of PV modules using particulate matter and precipitation forecasts.</li><li><strong>Snow effects:</strong> Model-based estimation of snow coverage and potential associated performance losses, taking snowfall, temperature, irradiance and module inclination into account.</li></ul><h2 id="what-might-it-look-like" tabindex="-1">What might it look like? <a class="header-anchor" href="#what-might-it-look-like" aria-label="Permalink to &quot;What might it look like?&quot;">​</a></h2><h5 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h5><p>The following figures show the output of solar radiation on 100x100m for Austria at two consecutive time steps.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="https://github.com/user-attachments/assets/d85df220-58a1-400d-9faa-bbcb1cd1e664" alt="infodienst_solar_step1"></th><th style="text-align:center;"><img src="https://github.com/user-attachments/assets/04db3bc8-5907-4b3c-8cfd-250d26366a81" alt="infodienst_solar_step2"></th></tr></thead></table><p>The output of this radiation model is then going to be converted into solar power generation potential by the method of <em>Jerez et al (2015)</em>. The output is the potential for the generated power. To obtain the power at the installed system, this value must be multiplied by the nominal installed watts.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="https://github.com/user-attachments/assets/dcf92c00-ab12-46e0-b433-601469fb58d7" alt="infodienst_solar_potential_step1"></th><th style="text-align:center;"><img src="https://github.com/user-attachments/assets/5e93041a-39d0-4d48-9469-5c1a86939032" alt="infodienst_solar_potential_step2"></th></tr></thead></table><h5 id="examples-of-spatial-representation" tabindex="-1">Examples of spatial representation <a class="header-anchor" href="#examples-of-spatial-representation" aria-label="Permalink to &quot;Examples of spatial representation&quot;">​</a></h5><p>The following figures show examples of global radiation and theoretical solar potential for the municipality of Baden on 5 March 2026. Comparing the 100 m and 1 m resolutions illustrates how local terrain, buildings and vegetation effects become more apparent at the finer resolution.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><sub><strong>11:00 UTC</strong></sub></th><th style="text-align:center;"><sub><strong>14:00 UTC</strong></sub></th></tr></thead><tbody><tr><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/e5d3580f1ff0a325cd158d6c42af78125f713eda/assets/vseitner/GLOreal100mBadencropped2026-03-05-1100-1793867873944.png" alt="GLO_real_100m_Baden_cropped_2026-03-05-1100.png"> <sub> GLO real (100m) </sub></td><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/87883185bc10345f61da72a4bbf1751f1f16f251/assets/vseitner/GLOreal100mBadencropped2026-03-05-1400-1793867893453.png" alt="GLO_real_100m_Baden_cropped_2026-03-05-1400.png"> <sub> GLO real (100m) </sub></td></tr><tr><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/13219b7e43f973fa596c36de97a2425925436045/assets/vseitner/PVpot100mBadencropped2026-03-05-1100-1793868225287.png" alt="PVpot_100m_Baden_cropped_2026-03-05-1100.png"> <sub> PV pot (100m) </sub></td><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/0a5d5632feb6625b8549401e343fa4ca2800b119/assets/vseitner/PVpot100mBadencropped2026-03-05-1400-1793868255134.png" alt="PVpot_100m_Baden_cropped_2026-03-05-1400.png"> <sub> PV pot (100m) </sub></td></tr><tr><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/bb48701d3b9e781c19dc0e1e919e39f454e88056/assets/vseitner/glorealdownscaled2026-03-05-1100-1793868489211.png" alt="glo_real_downscaled_2026-03-05-1100.png"> <sub> GLO real (1m) </sub></td><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/bcc2ce4edd8c540d76a2d594f2c09330d78e60d3/assets/vseitner/glorealdownscaled2026-03-05-1400-1793868513250.png" alt="glo_real_downscaled_2026-03-05-1400.png"> <sub> GLO real (1m) </sub></td></tr><tr><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/64a3272b2ac1c3b6b6bca15743a409a397b47a88/assets/vseitner/pvpotdownscaled2026-03-05-1100-1793868549275.png" alt="pvpot_downscaled_2026-03-05-1100.png"> <sub> PV pot (1m) </sub></td><td style="text-align:center;"><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/94ba0d2eb64de943fd3feec0376d62902e48287a/assets/vseitner/pvpotdownscaled2026-03-05-1400-1793868569892.png" alt="pvpot_downscaled_2026-03-05-1400.png"> <sub> PV pot (1m) </sub></td></tr></tbody></table><h2 id="technical-features" tabindex="-1">Technical features <a class="header-anchor" href="#technical-features" aria-label="Permalink to &quot;Technical features&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th style="text-align:right;"></th></tr></thead><tbody><tr><td>spatial resolution</td><td style="text-align:right;">100 m (up to 1m)</td></tr><tr><td>temporal resolution</td><td style="text-align:right;">1 hour</td></tr><tr><td>forecast range</td><td style="text-align:right;">+30 hours</td></tr><tr><td>forecast time</td><td style="text-align:right;">00 UTC</td></tr><tr><td>snow cover</td><td style="text-align:right;">yes/no</td></tr><tr><td>dust cover</td><td style="text-align:right;">yes/no</td></tr></tbody></table><p>The model chain can be adapted to any other region with some additional effort.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><h5 id="organisation" tabindex="-1">Organisation <a class="header-anchor" href="#organisation" aria-label="Permalink to &quot;Organisation&quot;">​</a></h5><p>This service is provided by <a href="https://www.geosphere.at/en" target="_blank" rel="noreferrer">GeoSphere Austria</a>.</p><h5 id="available-services" tabindex="-1">Available services <a class="header-anchor" href="#available-services" aria-label="Permalink to &quot;Available services&quot;">​</a></h5><ol><li><strong>Free Version</strong> <br> Example forecasts for selected muncipality during project runtime.</li><li><strong>Commercial version:</strong> upon request, please contact <a href="mailto:gerhard.wotawa@geosphere.at" target="_blank" rel="noreferrer">Gerhard Wotawa</a>, <a href="mailto:bernhard.niedermoser@geosphere.at" target="_blank" rel="noreferrer">Bernhard Niedermoser</a></li></ol><h6 id="scientific-background-and-references" tabindex="-1">Scientific Background and References <a class="header-anchor" href="#scientific-background-and-references" aria-label="Permalink to &quot;Scientific Background and References&quot;">​</a></h6><div style="font-size:10px;line-height:1.3;"><ul><li>Seitner et al. (2024): STRAHLGRID, a solar radiation model with applications across different spatial scales. <a href="https://doi.org/10.5194/ems2024-366" target="_blank" rel="noreferrer">https://doi.org/10.5194/ems2024-366</a></li><li>Hieden et al. (2011): The Integrated Nowcasting through Comprehensive Analysis (INCA) System and its validation over the Eastern Alpine Region. DOI: 10.1175/2010WAF2222451.1</li><li>Göbel et al. (2022): Development of a very high resolution solar radiation cadaster for estimating solar energy potential across the entire federal state of Salzburg, Austria. <a href="https://doi.org/10.5194/ems2022-396" target="_blank" rel="noreferrer">https://doi.org/10.5194/ems2022-396</a></li><li>Jerez et al. (2015): The impact of climate change on photovoltaic power generation in Europe. Nature Communications. <a href="https://doi.org/10.1038/ncomms10014" target="_blank" rel="noreferrer">https://doi.org/10.1038/ncomms10014</a></li><li>Olefs et al. (2020): Changes in snow depth, snow cover duration, and potential snowmaking conditions in Austria, 1961–2020 – a model based approach. Atmosphere, 11(12), 1330. <a href="https://doi.org/10.3390/atmos11121330" target="_blank" rel="noreferrer">https://doi.org/10.3390/atmos11121330</a></li><li>HSU Soiling Model, pvlib-python documentation: <a href="https://pvlib-python.readthedocs.io/en/latest/reference/generated/pvlib.soiling.hsu.html" target="_blank" rel="noreferrer">https://pvlib-python.readthedocs.io/en/latest/reference/generated/pvlib.soiling.hsu.html</a></li><li>NREL Snow Model, pvlib-python documentation: <a href="https://pvlib-python.readthedocs.io/en/stable/reference/effects_on_pv_system_output/snow.html" target="_blank" rel="noreferrer">https://pvlib-python.readthedocs.io/en/stable/reference/effects_on_pv_system_output/snow.html</a></li></ul></div>',36))],64)):c("",!0)])]))}});export{v as __pageData,_ as default};
